import { useState } from "react";
import { db, auth } from "../../firebase"; // Adjust path as needed
import { collection, addDoc, Timestamp } from "firebase/firestore";
import { Card, CardBody, CardTitle, Container, Row, Col, Button, Input, Label } from "reactstrap";

const CarbonInput = () => {
  const [date, setDate] = useState("");
  const [category, setCategory] = useState("Diet");
  const [carbonEmission, setCarbonEmission] = useState("");
  const [carbonCredits, setCarbonCredits] = useState(0);
  const [reductionProgress, setReductionProgress] = useState(0);
  const [rank, setRank] = useState("Bronze");

  const handleSave = async () => {
    if (!auth.currentUser) return;

    const emissionValue = parseFloat(carbonEmission);
    if (isNaN(emissionValue) || emissionValue <= 0) {
      alert("Please enter a valid carbon emission value.");
      return;
    }

    const calculatedCredits = emissionValue * 0.1; // Example calculation
    const newProgress = Math.max(0, 100 - (emissionValue * 2));
    const newRank = calculatedCredits > 50 ? "Gold" : calculatedCredits > 20 ? "Silver" : "Bronze";

    setCarbonCredits(calculatedCredits);
    setReductionProgress(newProgress);
    setRank(newRank);

    await addDoc(collection(db, "carbon_logs"), {
      userId: auth.currentUser.uid,
      date: Timestamp.fromDate(new Date(date)),
      category,
      carbonEmission: emissionValue,
      carbonCredits: calculatedCredits,
      reductionProgress: newProgress,
      rank: newRank,
    });
  };

  return (
    <Container fluid>
      <Row>
        <Col lg="6">
          <Label>Date</Label>
          <Input type="date" value={date} onChange={(e) => setDate(e.target.value)} />
        </Col>
        <Col lg="6">
          <Label>Category</Label>
          <Input type="select" value={category} onChange={(e) => setCategory(e.target.value)}>
            <option>Diet</option>
            <option>Transport</option>
            <option>Energy</option>
          </Input>
        </Col>
      </Row>
      <Row>
        <Col lg="6">
          <Label>Carbon Emission (kg CO₂)</Label>
          <Input type="number" value={carbonEmission} onChange={(e) => setCarbonEmission(e.target.value)} />
        </Col>
      </Row>
      <Row className="mt-3">
        <Col>
          <Button color="success" onClick={handleSave}>Save Data</Button>
        </Col>
      </Row>
      <Row className="mt-3">
        <Col>
          <Card className="bg-dark text-white">
            <CardBody>
              <CardTitle>Carbon Credits Earned: {carbonCredits.toFixed(2)}</CardTitle>
              <CardTitle>Carbon Reduction Progress: {reductionProgress.toFixed(2)}%</CardTitle>
              <CardTitle>Rank: {rank}</CardTitle>
            </CardBody>
          </Card>
        </Col>
      </Row>
    </Container>
  );
};

export default CarbonInput;
